                        q.append((nr, nc))
            rows = {}
            for rr, cc in cells:
                rows[rr] = rows.get(rr, 0) + 1
            if len(cells) != 4 or sorted(rows.values()) != [1, 3]:
                raise ValueError(f"Expected a four-cell T, got {cells}")
            top_count = rows[min(rows)]
            if top_count == 1:
                counts["up"] += 1
            else:
                counts["down"] += 1

